import {findIntroTarget} from './approved-intro-view.js';
const clamp=(n,a,b)=>Math.max(a,Math.min(Math.max(a,b),n));
export function createLearningView({document:doc,onPrimary,onLater,onPick,onTraining,onGuide,onResume,onToggle,onSkipTraining,onRetryHelp,onBriefing}){
 const win=doc.defaultView,root=doc.createElement('section');root.id='gvLearningHost';root.hidden=true;root.setAttribute('popover','manual');root.innerHTML='<div class="gl-shade" hidden></div><div class="gl-ring" hidden></div><section class="gl-window" aria-label="Aprender no GemVenture"><header class="gl-head"><span class="gl-eyebrow">APRENDER</span><button type="button" class="gl-button gl-close" data-later aria-label="Deixar para depois">×</button></header><div class="gl-lesson"><img class="gl-art" alt="" draggable="false"><div><h2 tabindex="-1"></h2><p class="gl-copy" aria-live="polite"></p></div></div><label class="gl-name" hidden>Seu nome<input maxlength="24" autocomplete="nickname" aria-label="Seu nome de minerador"></label><div class="gl-goal" hidden></div><div class="gl-help" role="status" hidden></div><button class="gl-button" type="button" data-retry-help hidden>Tentar salvar ajuda</button><button class="gl-button" type="button" data-skip-training hidden>Ir para a expedição</button><div class="gl-progress" hidden><span></span><div><i></i></div></div><div class="gl-error" role="alert" hidden></div><nav class="gl-library-actions" hidden><button class="gl-button gl-primary primary" type="button" data-resume>Retomar jornada</button><button class="gl-button" type="button" data-briefing>Guia da expedição</button><button class="gl-button" type="button" data-training>Treino livre</button><button class="gl-button" type="button" data-guide>Guia do Refúgio</button><button class="gl-button" type="button" data-toggle>Dicas ligadas</button></nav><div class="gl-library" hidden></div><footer class="gl-actions"><button class="gl-button gl-secondary" type="button" data-secondary>Depois</button><button class="gl-button gl-primary" type="button" data-primary="true">Continuar</button></footer></section>';doc.body.append(root);
 const css=doc.createElement('link');css.rel='stylesheet';css.href=new URL('./learning-ui.css',import.meta.url).href;doc.head.append(css);
 const q=s=>root.querySelector(s),panel=q('.gl-window'),name=q('input');let current=null,lastKey='',opener=null;
 q('[data-primary]').onclick=e=>{if(e.detail<=1)onPrimary(name.value);};q('[data-later]').onclick=onLater;q('[data-secondary]').onclick=()=>current?.kind==='sound'?onPrimary(null,{silent:true}):onLater();q('[data-briefing]').onclick=onBriefing;q('[data-training]').onclick=onTraining;q('[data-guide]').onclick=onGuide;q('[data-resume]').onclick=onResume;q('[data-toggle]').onclick=onToggle;
 q('[data-skip-training]').onclick=onSkipTraining;q('[data-retry-help]').onclick=onRetryHelp;
 name.onkeydown=e=>{if(e.key==='Enter'&&!e.repeat){e.preventDefault();onPrimary(name.value);}};
 function layout(){if(root.hidden||!current)return;const modal=doc.querySelector('dialog[open]'),parent=modal||doc.body;if(root.parentElement!==parent){if(root.matches?.(':popover-open'))root.hidePopover();parent.append(root);}let inheritedZoom=1;for(let node=parent;node;node=node.parentElement){const value=win.getComputedStyle(node).zoom||'1';inheritedZoom*=parseFloat(value)/(value.endsWith('%')?100:1)||1;}root.style.zoom=String(1/inheritedZoom);if(typeof root.showPopover==='function'&&!root.matches(':popover-open'))root.showPopover();
  const W=win.innerWidth,H=win.innerHeight,scale=parseFloat(win.getComputedStyle(doc.documentElement).getPropertyValue('--gv-ui-scale'))||1;panel.style.zoom=String(scale);panel.style.maxHeight=(H-24)/scale+'px';const rect=panel.getBoundingClientRect(),pw=rect.width,ph=rect.height,target=current.target&&findIntroTarget(doc,current.target),r=target?.getBoundingClientRect(),usable=r&&r.width&&r.height&&r.bottom>0&&r.right>0&&r.left<W&&r.top<H;
  let x=(W-pw)/2,y=(H-ph)/2;if(current.kind==='lesson'&&usable){if(r.right+pw+24<W){x=r.right+12;y=r.top;}else if(r.left-pw-12>=12){x=r.left-pw-12;y=r.top;}else if(r.bottom+ph+24<H){x=(W-pw)/2;y=r.bottom+12;}else{x=12;y=Math.max(12,r.top-ph-12);}}
  Object.assign(panel.style,{left:clamp(x,12,W-pw-12)/scale+'px',top:clamp(y,12,H-ph-12)/scale+'px'});const ring=q('.gl-ring');ring.hidden=!usable||current.kind!=='lesson';if(!ring.hidden)Object.assign(ring.style,{left:Math.max(2,r.left-4)+'px',top:Math.max(2,r.top-4)+'px',width:r.width+8+'px',height:r.height+8+'px'});
 }
 function render(model){const wasActive=!root.hidden;current=model;if(!model){if(root.matches?.(':popover-open'))root.hidePopover();root.hidden=true;lastKey='';if(wasActive)(opener?.isConnected&&opener.getClientRects().length?opener:doc.getElementById('tutorialButton'))?.focus?.({preventScroll:true});return;}if(!wasActive)opener=doc.activeElement;root.hidden=false;root.dataset.kind=model.kind;root.dataset.topic=model.topic||'';q('.gl-eyebrow').textContent=model.kind==='briefing'?'GUIA DA EXPEDIÇÃO':'APRENDER';panel.classList.toggle('gl-catalog',model.kind==='catalog');q('.gl-shade').hidden=model.kind==='lesson';q('h2').textContent=model.title;q('.gl-copy').textContent=model.text||'';q('.gl-art').src=model.image||'assets/hud-v5/home.png';q('.gl-name').hidden=model.kind!=='welcome';if(model.kind==='welcome'&&lastKey!=='welcome')name.value=model.name||'';
  root.setAttribute('role',model.kind==='lesson'?'region':'dialog');if(model.kind==='lesson')root.removeAttribute('aria-modal');else root.setAttribute('aria-modal','true');q('.gl-progress').hidden=!model.total;if(model.total){q('.gl-progress span').textContent=(model.index+1)+' / '+model.total;q('.gl-progress i').style.width=(model.index+1)/model.total*100+'%';}
  q('[data-skip-training]').hidden=!['sound','practice'].includes(model.foundation);q('[data-retry-help]').hidden=!model.retryHelp;q('.gl-help').hidden=!model.helpError;q('.gl-help').textContent=model.helpError||'';const goal=q('.gl-goal');goal.hidden=!model.goal;goal.replaceChildren();if(model.goal){for(const text of model.goal.lines){const row=doc.createElement('p');row.textContent=text;goal.append(row);}}
  q('[data-primary]').textContent=model.primary||'Entendi';q('[data-secondary]').textContent=model.secondary||(model.kind==='sound'?'Treinar sem som':'Depois');q('.gl-actions').hidden=model.kind==='catalog';q('.gl-library-actions').hidden=model.kind!=='catalog';const list=q('.gl-library');list.hidden=model.kind!=='catalog';q('[data-toggle]').textContent=model.paused?'Dicas pausadas':'Dicas ligadas';q('[data-resume]').hidden=!model.resume;q('[data-briefing]').hidden=!model.briefingAvailable;
  if(model.kind==='catalog'){list.replaceChildren();for(const topic of model.topics){const b=doc.createElement('button');b.type='button';b.className='gl-topic';b.disabled=!topic.available;b.dataset.learningTopic=topic.id;const img=doc.createElement('img');img.src=topic.image;img.alt='';const copy=doc.createElement('span'),strong=doc.createElement('strong'),small=doc.createElement('small');strong.textContent=topic.name;small.textContent=topic.available?(topic.seen?'Rever':'Novo'):(topic.requirement||'Mais adiante');copy.append(strong,small);b.append(img,copy);b.onclick=()=>onPick(topic.id);list.append(b);}}
  q('.gl-error').hidden=true;layout();const key=model.kind+':'+(model.topic||'')+':'+(model.index||0);if(key!==lastKey){lastKey=key;if(model.kind==='welcome')name.focus({preventScroll:true});else q('h2').focus({preventScroll:true});}
 }
 const key=e=>{if(root.hidden)return;if(e.repeat&&['Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();return;}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();onLater();return;}if(e.key==='Tab'&&current?.kind!=='lesson'){const nodes=[...panel.querySelectorAll('button,input')].filter(e=>!e.disabled&&e.getClientRects().length),i=nodes.indexOf(doc.activeElement);if(nodes.length){e.preventDefault();nodes[(i+(e.shiftKey?-1:1)+nodes.length)%nodes.length].focus();}}};doc.addEventListener('keydown',key,true);win.addEventListener('resize',layout);
 return {render,layout,error(text){q('.gl-error').textContent=text;q('.gl-error').hidden=false;layout();},get active(){return !root.hidden;},root,dispose(){doc.removeEventListener('keydown',key,true);win.removeEventListener('resize',layout);root.remove();css.remove();}};
}
